  bool pressed = gpio_get_level((gpio_num_t)pin) == 0;
  EdgeRecord &e = edgeLog[edgeCount % kEdgeLogSize];
  e.ms = now;
  e.button = (uint8_t)name;
  e.released = pressed ? 0 : 1;
  edgeCount = edgeCount + 1;
  lastEdgeMs = now;
  button_latch_edge(latch, pressed, now);
